/bin/bash -lc "python3 - <<'PY'
import ast,hashlib,json,subprocess
from pathlib import Path
root=Path('/workspace'); p=json.loads((root/'proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
def check(x,s,path='"'$'"'):
    typ=s.get('type')
    if typ:
        types={'object':dict,'array':list,'string':str,'integer':int,'number':(int,float),'boolean':bool,'null':type(None)}
        assert isinstance(x,types[typ]),(path,'type',typ)
    if 'const' in s: assert x==s['const'],(path,'const')
    if 'enum' in s: assert x in s['enum'],(path,'enum')
    if isinstance(x,dict):
        for key in s.get('required',[]): assert key in x,(path,'required',key)
        props=s.get('properties',{})
        if s.get('additionalProperties') is False: assert set(x)<=set(props),(path,'extra',set(x)-set(props))
        for key,value in x.items():
            if key in props: check(value,props[key],path+'.'+key)
    if isinstance(x,list):
        assert len(x)>=s.get('minItems',0),(path,'minItems')
        for i,value in enumerate(x): check(value,s.get('items',{}),path+f'[{i}]')
    if isinstance(x,str): assert len(x)>=s.get('minLength',0),(path,'minLength')
check(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4
assert any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert {(v['config']['group_slots'],v['config']['target_query']) for v in p['variants']}=={(True,True),(False,True),(True,False),(False,False)}
classes=[]
for v in p['variants']:
    assert v['role'] in {'candidate','control'}
    assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
    text=(root/v['file']).read_text(); tree=ast.parse(text);compile(text,v['file'],'exec')
    cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
    assert cfg==v['config']
    assert hashlib.sha256(text.encode()).hexdigest() in v['note']
    cls=next(n for n in tree.body if isinstance(n,ast.ClassDef));classes.append(ast.dump(cls,include_attributes=False))
    methods={n.name for n in cls.body if isinstance(n,ast.FunctionDef)}
    assert {'__init__','forward','diagnostics'}<=methods
assert len(set(classes))==1
required={'taac2026-academic-1-craft','taac2026-academic-2-unidac','taac2026-academic-3-unitokenformer','taac2026-industry-1-queryformer','taac2026-industry-2-unidot'}
assert required<= {a['knowledge_id'] for a in p['knowledge_assessments']}
for a in p['knowledge_assessments']:
    assert a['decision'] in {'used','considered','rejected','unresolved'}
    assert set(a['variant_names'])=={v['name'] for v in p['variants']}
print('PASS: runtime study schema, protocol, allowed evidence, 4-cell factorial, literal configs, standalone modules, hashes, AST equality, knowledge coverage.')
print('PASS: initial known parent source digest agrees with resolved trial receipt.')
# All evidence is registry-resolvable, including trajectories only summarized in runtime.
for evidence in p['study']['evidence_refs']:
    receipt=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','trial://'+evidence],text=True))
    assert receipt['id']==evidence
    print(evidence,receipt['status'],round(receipt['validation']['auc'],9),round(receipt['validation']['logloss'],9))
# Verify primary source implementation digests.
for filename,evidence in [('history_g1_r0006_paired_match.py','g1-r0006-paired_match'),('history_g2_r0001_target_separate.py','g2-r0001-target_separate')]:
    receipt=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','trial://'+evidence],text=True))
    assert hashlib.sha256((root/filename).read_bytes()).hexdigest()==receipt['source_sha256']
print('PASS: both frozen source implementation hashes match their own receipts.')
PY"

